<script setup lang="ts">
import {computed,ref,watch,onScopeDispose} from 'vue';
import type {ViewModel} from '../app/useWorkspace';
import {cleanNativePresetConfig,encodeNativePresetDraft,decodeNativePresetDraft,type NativePresetConfig} from '../domain/nativePreset';
import {cleanNativeWorldbook,readNativeWorldbookFile,emptyNativeWorldbooks,removeNativeWorldbook,type NativeWorldbooks} from '../domain/nativeWorldbooks';
import {nativePresetTasks,type NativePresetTask} from '../domain/nativeTasks';
import {configurationEditors} from '../app/configurationEditors';
import {registerBackupFlusher} from '../app/backupFlushers';
import {useAutoSave} from '../app/useAutoSave';
import FileImportButton from './FileImportButton.vue';
const props=defineProps<{w:ViewModel}>();defineEmits<{legacy:[]}>();
const saved=computed(()=>props.w.nativePreset||props.w.nativeDefaultPreset),draft=ref<NativePresetConfig>(),baseline=ref(''),problem=ref(''),ready=ref(false),committing=ref(false),selected=ref(''),sid=ref(props.w.active?.id||'');
const pendingPresetRaw=ref(false);
const key='preset:native-runtime',blocked=computed(()=>props.w.busy||props.w.workingMemory||props.w.terminalBusy||props.w.backupWorking||props.w.savingNativePreset||props.w.unsafeNativeDrafts||pendingPresetRaw.value),dirty=computed(()=>!!draft.value&&JSON.stringify(draft.value)!==baseline.value);
const library=computed(()=>draft.value?.worldbooks),book=computed(()=>library.value?.books.find(b=>b.id===selected.value)||library.value?.books[0]);
function reset(){if(!saved.value)return;draft.value=cleanNativePresetConfig(saved.value);baseline.value=JSON.stringify(saved.value);problem.value='';pendingPresetRaw.value=false;}
let revision=0;
watch(saved,async()=>{if(dirty.value||committing.value)return;ready.value=false;reset();const n=++revision;try{const text=await props.w.readEditorDraft(key);if(text&&n===revision){const restored=decodeNativePresetDraft(text,draft.value!);if(restored.rawText!==JSON.stringify(restored.config.preset,null,2)){pendingPresetRaw.value=true;throw Error('请先在预设页处理尚未应用的完整 JSON 草稿。');}draft.value=restored.config;}}catch(e){pendingPresetRaw.value=true;problem.value=e instanceof Error?e.message:'草稿载入失败';}finally{if(n===revision)ready.value=true;}},{immediate:true});
const autoSave=useAutoSave(()=>ready.value&&dirty.value?JSON.stringify(draft.value):'',async()=>{await props.w.saveEditorDraft(key,dirty.value?encodeNativePresetDraft(draft.value!,JSON.stringify(draft.value!.preset,null,2)):null);return true;},400,()=>!ready.value||props.w.loading||props.w.backupWorking||props.w.unsafeNativeDrafts||pendingPresetRaw.value);
function edit(action:(books:NativeWorldbooks)=>void){if(!draft.value||blocked.value||pendingPresetRaw.value)return;try{const next=cleanNativePresetConfig(draft.value);next.worldbooks??=emptyNativeWorldbooks();action(next.worldbooks);draft.value=cleanNativePresetConfig(next);problem.value='';}catch(e){problem.value=e instanceof Error?e.message:'世界书未修改';}}
function add(name='新世界书',raw:unknown={entries:{}}){const id=crypto.randomUUID();edit(books=>{books.books.push({id,name:name.slice(0,100)||'新世界书',worldbook:cleanNativeWorldbook(raw)});});if(library.value?.books.some(b=>b.id===id))selected.value=id;}
async function importFile(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];try{if(file)add(file.name.replace(/\.json$/i,''),await readNativeWorldbookFile(file));}catch(e){problem.value=e instanceof Error?e.message:'世界书文件无法读取';}finally{input.value='';}}
async function save(){if(!draft.value||blocked.value)return;committing.value=true;problem.value='';try{if(pendingPresetRaw.value)throw Error('请先在预设页处理尚未应用的完整 JSON 草稿。');if(JSON.stringify(saved.value)!==baseline.value)throw Error('配置已被其他操作修改，请取消后重新编辑。');const value=cleanNativePresetConfig(draft.value);value.worldbooks??=emptyNativeWorldbooks();await props.w.saveNativePreset(value);draft.value=value;baseline.value=JSON.stringify(value);await props.w.saveEditorDraft(key,null);}catch(e){problem.value=e instanceof Error?e.message:'世界书未保存';}finally{committing.value=false;}}
async function cancel(){autoSave.cancel();revision++;reset();await props.w.saveEditorDraft(key,null);}
function exportFile(){if(!book.value)return;try{const raw=cleanNativeWorldbook(book.value.worldbook),url=URL.createObjectURL(new Blob([JSON.stringify(raw,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=book.value.name+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){problem.value=e instanceof Error?e.message:'世界书无法导出';}}
function bind(kind:'default'|'task'|'session',id:string,enabled:boolean,task?:NativePresetTask){edit(books=>{let list=books.defaultIds;if(kind==='task'&&task){books.taskBooks??={};list=books.taskBooks[task]??=[];}if(kind==='session'){if(!sid.value)return;books.sessionBooks??={};list=books.sessionBooks[sid.value]??=[];}const at=list.indexOf(id);if(enabled&&at<0)list.push(id);if(!enabled&&at>=0)list.splice(at,1);});}
function override(kind:'task'|'session',enabled:boolean,task?:NativePresetTask){edit(books=>{if(kind==='task'&&task){books.taskBooks??={};if(enabled)books.taskBooks[task]=[...books.defaultIds];else delete books.taskBooks[task];}if(kind==='session'&&sid.value){books.sessionBooks??={};if(enabled)books.sessionBooks[sid.value]=[...books.taskBooks?.story||books.defaultIds];else delete books.sessionBooks[sid.value];}});}
function addEntry(){if(!book.value)return;const id=book.value.id;edit(books=>{const raw=books.books.find(b=>b.id===id)!.worldbook,uid=Math.max(-1,...Object.keys(raw.entries).map(Number))+1;raw.entries[uid]={uid,key:[],keysecondary:[],comment:'新条目',content:'',constant:false,selective:false,disable:false,order:100,position:0,depth:4,probability:100,useProbability:true,group:'',groupOverride:false,groupWeight:100};});}
function keys(event:Event,entry:any,field:string){entry[field]=(event.target as HTMLTextAreaElement).value.split(/[\n,，]/).map(s=>s.trim()).filter(Boolean);}
const unregister=configurationEditors()?.('native-worldbooks',{dirty:()=>dirty.value,save:async()=>{await save();if(problem.value)throw Error(problem.value);},discard:cancel});if(unregister)onScopeDispose(unregister);registerBackupFlusher(async()=>{await autoSave.flush();if(autoSave.error.value)throw Error(autoSave.error.value);});
</script>
<template>
 <section class="surface native-worldbook-settings">
  <header class="panel-heading"><div><p class="eyebrow">WORLDBOOKS</p><h1>世界书</h1></div><div class="actions"><FileImportButton label="导入原生世界书" accept=".json,application/json" :disabled="blocked" @change="importFile"/><button :disabled="blocked||!draft" @click="save">保存世界书</button><button :disabled="blocked||!dirty" @click="cancel">取消修改</button><button @click="$emit('legacy')">旧版世界书</button></div></header>
  <p role="status">{{dirty?'有未保存的修改':'预设与世界书共用已保存配置；完整备份包含全部文件和绑定。'}}</p><p class="rail-note">保存会同时提交预设与世界书草稿。保存原生世界书配置后，原生调用使用本页绑定；旧版资料保留在旧版页面。</p>
  <p v-if="problem||autoSave.error.value" class="error" role="alert">{{problem||autoSave.error.value}}</p>
  <template v-if="draft">
   <div class="actions"><button :disabled="blocked||(library?.books.length||0)>=20" @click="add()">新建世界书</button><label>当前世界书<select aria-label="当前原生世界书" :value="book?.id||''" @change="selected=($event.target as HTMLSelectElement).value"><option v-for="b in library?.books||[]" :key="b.id" :value="b.id">{{b.name}}</option></select></label></div>
   <details v-if="library?.books.length" class="subsection"><summary>世界书绑定</summary><p>未指定存档时使用任务绑定；任务未指定时使用默认绑定。指定存档的独立绑定优先用于其正文、记忆及终端。</p>
    <fieldset :disabled="blocked"><legend>默认绑定</legend><label v-for="b in library.books" :key="b.id" class="toggle"><input type="checkbox" :aria-label="'默认使用 '+b.name" :checked="library.defaultIds.includes(b.id)" @change="bind('default',b.id,($event.target as HTMLInputElement).checked)"/>{{b.name}}</label></fieldset>
    <details v-for="(label,task) in nativePresetTasks" :key="task"><summary>{{label}}</summary><label class="toggle"><input type="checkbox" :aria-label="label+'独立世界书绑定'" :checked="library.taskBooks?.[task]!==undefined" :disabled="blocked" @change="override('task',($event.target as HTMLInputElement).checked,task)"/>使用独立绑定</label><label v-for="b in library.books" v-show="library.taskBooks?.[task]!==undefined" :key="b.id" class="toggle"><input type="checkbox" :disabled="blocked" :aria-label="label+'使用 '+b.name" :checked="library.taskBooks?.[task]?.includes(b.id)" @change="bind('task',b.id,($event.target as HTMLInputElement).checked,task)"/>{{b.name}}</label></details>
    <label>存档<select v-model="sid" aria-label="世界书绑定存档"><option value="">请选择存档</option><option v-for="s in w.sessions" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label v-if="sid" class="toggle"><input type="checkbox" aria-label="存档独立世界书绑定" :checked="library.sessionBooks?.[sid]!==undefined" :disabled="blocked" @change="override('session',($event.target as HTMLInputElement).checked)"/>此存档使用独立绑定</label><label v-for="b in library.books" v-show="sid&&library.sessionBooks?.[sid]!==undefined" :key="b.id" class="toggle"><input type="checkbox" :disabled="blocked" :aria-label="'存档使用 '+b.name" :checked="library.sessionBooks?.[sid]?.includes(b.id)" @change="bind('session',b.id,($event.target as HTMLInputElement).checked)"/>{{b.name}}</label>
   </details>
   <template v-if="book"><label>世界书名称<input v-model="book.name" aria-label="原生世界书名称" maxlength="100" :disabled="blocked"/></label><div class="actions"><button :disabled="blocked" @click="add(book.name+' 副本',book.worldbook)">复制世界书</button><button :disabled="blocked" @click="edit(books=>Object.assign(books,removeNativeWorldbook(books,book!.id)))">删除世界书</button><button :disabled="blocked" @click="exportFile">导出世界书</button><button :disabled="blocked" @click="addEntry">新增条目</button></div>
    <details v-for="(entry,id) in book.worldbook.entries" :key="book.id+id" class="subsection"><summary>{{entry.comment||'条目 '+id}}</summary><fieldset :disabled="blocked"><label>名称<input v-model="entry.comment"/></label><label class="toggle"><input type="checkbox" :checked="entry.disable!==true" :aria-label="'启用世界书条目 '+id" @change="entry.disable=!($event.target as HTMLInputElement).checked"/>启用</label><label class="toggle"><input v-model="entry.constant" type="checkbox" :aria-label="'常驻世界书条目 '+id"/>常驻</label><label>主要关键词<textarea :value="entry.key?.join('\n')" :aria-label="'世界书关键词 '+id" rows="2" @input="keys($event,entry,'key')"/></label><label>次要关键词<textarea :value="entry.keysecondary?.join('\n')" rows="2" @input="keys($event,entry,'keysecondary')"/></label><label>内容<textarea v-model="entry.content" :aria-label="'世界书内容 '+id" rows="7"/></label><div class="field-grid"><label>插入位置<input v-model.number="entry.position" type="number"/></label><label>顺序<input v-model.number="entry.order" type="number"/></label><label>深度<input v-model.number="entry.depth" type="number"/></label><label>触发概率<input v-model.number="entry.probability" type="number" min="0" max="100"/></label></div><details><summary>原始字段</summary><pre>{{JSON.stringify(entry,null,2)}}</pre></details><button @click="edit(books=>{delete books.books.find(b=>b.id===book!.id)!.worldbook.entries[id]})">删除条目</button></fieldset></details>
    <details class="subsection"><summary>完整原始文件</summary><pre>{{JSON.stringify(book.worldbook,null,2)}}</pre></details>
   </template><p v-else>新建或导入一份自己的世界书，然后选择需要使用它的任务。</p>
  </template>
 </section>
</template>
<style scoped>
fieldset{border:0;padding:0;min-width:0}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:24rem;overflow:auto}select{max-width:100%}.actions{flex-wrap:wrap}.panel-heading{flex-wrap:wrap}.panel-heading>div:first-child{min-width:8rem;flex-shrink:0}.panel-heading>.actions{flex:1 1 24rem}.subsection{margin:1rem 0}label{margin:.6rem 0}
</style>
